schema:
entity Role enum ["owner", "developer", "operator", "orgAdmin"];

entity Environment enum ["production", "nonProduction"];

entity User {
    roles: Set<Role>,
    orgMembership: OrgUnit,
};

entity OrgUnit in [OrgUnit];

entity CloudResource {
    owner: User,
    orgUnit: OrgUnit,
    tags: Set<String>,
    environment: Environment,
    temporaryGrant: Bool,
    promoted: Bool,
};

entity Secret;

action modifyCloudResource appliesTo {
    principal: [User],
    resource: [CloudResource],
    context: {
        sourceIp: ipaddr,
        mfaUsed: Bool,
        sessionAge: duration,
    },
};

entity Role enum ["Author", "Editor", "Viewer", "ComplianceOfficer"];

entity User {
    roles: Set<Role>,
};

entity Document {
    owner: User,
    shareList: Set<User>,
    classification: String,
    hasVersionLock: Bool,
    labels: Set<String>,
    status: String,
};

entity Workspace {
    members: Set<User>,
};

action editDocument appliesTo {
    principal: [User],
    resource: [Document],
};

entity User {
    roles: Set<String>,
    clearance: Long,
};

entity EmployeeRecord {
    employee: User,
    manager: User,
    piiLevel: Long,
    department: String,
};

entity PayrollRun;

entity LeaveRequest;

action viewEmployeeRecord appliesTo {
    principal: [User],
    resource: [EmployeeRecord],
    context: {
        onCorporateVpn: Bool,
        currentTime: datetime,
    },
};

action preparePayrollRun appliesTo {
    principal: [User],
    resource: [PayrollRun],
    context: {
        onCorporateVpn: Bool,
        currentTime: datetime,
    },
};

action approveLeaveRequest appliesTo {
    principal: [User],
    resource: [LeaveRequest],
    context: {
        onCorporateVpn: Bool,
        currentTime: datetime,
    },
};

entity Person {
    isOriginator: Bool,
    isVerifier: Bool,
    isTreasuryOfficer: Bool,
    isComplianceReviewer: Bool,
    authorityTier: Long,
};

entity Account {
    holder: Person,
    allowedBeneficiaries: Set<String>,
};

entity WireTransfer {
    initiatedBy: Person,
    verifiedBy?: Person,
    screenedBy: Person,
    account: Account,
    amount: decimal,
    fee: decimal,
    amountTier: Long,
    beneficiary: String,
    currencyCode: String,
    isHighRisk: Bool,
    status: String,
    approvalThreshold: Long,
    moneyThreshold: Long,
    amountPlusFeeExceedsApprovalThreshold: Bool,
    amountExceedsMoneyThreshold: Bool,
};

entity Beneficiary;

entity WireStatus enum ["Approved", "Released"];

action approveWire appliesTo {
    principal: [Person],
    resource: [WireTransfer],
    context: {
        currentTime: datetime,
        dailyCutoff: datetime,
        cameFromSecureNetwork: Bool,
        mfaUsed: Bool,
        emergencyDeclared: Bool,
        approvalThreshold: decimal,
    },
};

action releaseWire appliesTo {
    principal: [Person],
    resource: [WireTransfer],
    context: {
        currentTime: datetime,
        dailyCutoff: datetime,
        cameFromSecureNetwork: Bool,
        mfaUsed: Bool,
        emergencyDeclared: Bool,
        releaseMoneyThreshold: decimal,
    },
};

entity Role enum ["patentAttorney", "docketClerk", "examiner", "inventor"];

entity Person {
    roles: Set<Role>,
    clearance: String,
};

entity Team;

entity PatentApplication {
    inventor: Person,
    prosecutingAttorney: Person,
    assignedExaminer: Person,
    team: Team,
    confidentiality: String,
    barDate: datetime,
    status: String,
};

entity OfficeAction;

entity Filing;

action examinePatentApplication appliesTo {
    principal: [Person],
    resource: [PatentApplication],
    context: {
        currentDate: datetime,
        onFirmNetwork: Bool,
        hasCourtOrder: Bool,
        mfaUsed: Bool,
    },
};

entity Person {
    approvalTier: String,
};

entity Employee {
    person: Person,
};

entity LineManager {
    person: Person,
};

entity FinanceReviewer {
    person: Person,
};

entity Controller {
    person: Person,
};

entity ExpenseReport {
    submitter: Employee,
    approver: LineManager,
    totalAmount: decimal,
    mealTotal: decimal,
    lodgingTotal: decimal,
    category: String,
    amountTier: String,
    receiptAttached: Bool,
    status: String,
    submittedAt: datetime,
};

entity Reimbursement {
    expenseReport: ExpenseReport,
    disbursedBy: Controller,
    amount: decimal,
};

action disburseReimbursement appliesTo {
    principal: [Controller],
    resource: [Reimbursement],
    context: {
        onCorporateNetwork: Bool,
        currentTime: datetime,
        emergencyApproval: Bool,
        businessHours: Bool,
    },
};

entity Role enum ["PharmacyTechnician", "StaffPharmacist", "PharmacistInCharge", "Prescriber", "Exception"];

entity PrescriptionStatus enum ["Received", "OutsideReceived"];

entity User {
    roles: Set<Role>,
    dispenseAuthority: Bool,
    stateLicense: String,
};

entity Patient;

entity Prescription {
    prescriber: User,
    patient: Patient,
    enteredBy: User,
    verifiedBy?: User,
    prescriberDea: String,
    scheduleLevel: String,
    refillsRemaining: Long,
    status: PrescriptionStatus,
};

entity DispenseRecord;

action verifyPrescription appliesTo {
    principal: [User],
    resource: [Prescription],
    context: {
        pdmpChecked: Bool,
        mfaUsed: Bool,
        fromPharmacyNetwork: Bool,
        currentTime: datetime,
        emergencyOverrideUsed: Bool,
        refillsRemainingCrossesThreshold: Bool,
    },
};

entity Person {
    roles: Set<Role>,
};

entity Role enum ["Planner", "ShiftSupervisor", "Operator", "ControlRoomOperator", "Auditor"];

entity Feeder;

entity SwitchingOrderStatus enum ["Authorized", "Unauthorized"];

entity SwitchingOrder {
    planner: Person,
    executor: Person,
    feeder: Feeder,
    voltageLevel: String,
    circuitCount: Long,
    status: SwitchingOrderStatus,
    scheduledStart: datetime,
    scheduledEnd: datetime,
    requiresControlRoomHandling: Bool,
};

entity LockoutTag {
    order: SwitchingOrder,
    appliedBy: Person,
    feeder: Feeder,
};

action executeSwitching appliesTo {
    principal: [Person],
    resource: [SwitchingOrder],
    context: {
        currentTime: datetime,
        onScadaNetwork: Bool,
        lockoutTagoutVerified: Bool,
        outageEmergencyDeclared: Bool,
    },
};

entity Role enum ["Drafter", "Reviewer", "Signatory", "ContractAdministrator"];

entity Person {
    roles: Set<Role>,
    delegatedAuthorityTier: Long,
    conflictedCounterparties: Set<Counterparty>,
};

entity Counterparty;

entity ContractStatus enum ["Draft", "Reviewed", "Signed", "Executed"];

entity Contract {
    drafter: Person,
    reviewer: Person,
    counterparty: Counterparty,
    contractValue: decimal,
    requiredAuthorityTier: Long,
    effectiveDate: datetime,
    status: ContractStatus,
};

entity Signature {
    contract: Contract,
    signer: Person,
    amount: decimal,
};

action reviewContract appliesTo {
    principal: [Person],
    resource: [Contract],
    context: {
        currentDate: datetime,
        fromCorporateNetwork: Bool,
        mfaUsed: Bool,
        escalationApproved: Bool,
    },
};

action signContract appliesTo {
    principal: [Person],
    resource: [Signature],
    context: {
        currentDate: datetime,
        fromCorporateNetwork: Bool,
        mfaUsed: Bool,
        escalationApproved: Bool,
    },
};

action executeContract appliesTo {
    principal: [Person],
    resource: [Contract],
    context: {
        currentDate: datetime,
        fromCorporateNetwork: Bool,
        mfaUsed: Bool,
        escalationApproved: Bool,
    },
};

entity User {
    isAnalyst: Bool,
    isOfficer: Bool,
    isSecurityAdmin: Bool,
    isContractor: Bool,
    clearance: Long,
    compartments: Set<String>,
    nationality: String,
};

entity Document {
    owner: User,
    classification: Long,
    compartments: Set<String>,
    status: String,
};

entity Dossier;

entity AccessBadge;

action readDocument appliesTo {
    principal: [User],
    resource: [Document],
    context: {
        fromIntranet: Bool,
        currentTime: datetime,
        relevantCompartment: String,
    },
};

entity Person {
    isEscrowOfficer: Bool,
    isSeniorEscrowOfficer: Bool,
    isEscrowManager: Bool,
    isTitleOfficer: Bool,
    isAuditor: Bool,
};

entity EscrowFile {
    escrowOfficer: Person,
    openedBy: Person,
    disbursementTier: String,
    amountHeld: decimal,
    numberOfPayees: Long,
    fileCode: String,
    region: String,
    parties: Set<String>,
    lienStatus: String,
    titleCleared: Bool,
    status: String,
    closingDate: datetime,
};

entity Disbursement {
    escrowFile: EscrowFile,
    authorizedBy: Person,
    amount: decimal,
    wiredAt: datetime,
};

entity AuditLog;

action openEscrowFile appliesTo {
    principal: [Person],
    resource: [EscrowFile],
    context: {
        currentTime: datetime,
        fromCorporateNetwork: Bool,
        dualControlConfirmed: Bool,
        settlementEmergencyDeclared: Bool,
    },
};

action approveClearToClose appliesTo {
    principal: [Person],
    resource: [EscrowFile],
    context: {
        currentTime: datetime,
        fromCorporateNetwork: Bool,
        dualControlConfirmed: Bool,
        settlementEmergencyDeclared: Bool,
    },
};

action viewAuditLog appliesTo {
    principal: [Person],
    resource: [AuditLog],
    context: {
        currentTime: datetime,
        fromCorporateNetwork: Bool,
        dualControlConfirmed: Bool,
        settlementEmergencyDeclared: Bool,
    },
};

entity Role enum ["instructorOfRecord", "teachingAssistant", "learner", "coordinator"];

entity ModuleStatus enum ["draft", "scheduled", "released"];

entity User {
    roles: Set<Role>,
    completedLevel: Long,
};

entity Course;

entity Module {
    course: Course,
    instructorOfRecord: User,
    roster: Set<User>,
    prerequisiteLevel: Long,
    releaseTime: datetime,
    locked: Bool,
    status: ModuleStatus,
};

entity GradeEntry {
    learner: User,
    module: Module,
    poster: User,
    status: String,
};

action viewModule appliesTo {
    principal: [User],
    resource: [Module],
    context: {
        currentTime: datetime,
        fromInstitutionNetwork: Bool,
        previewWindow: duration,
    },
};

entity User;

entity Instructor {
    user: User,
};

entity Student {
    user: User,
};

entity Parent {
    user: User,
};

entity Registrar {
    user: User,
};

entity StudentRecord {
    student: Student,
    advisor: Instructor,
    age: Long,
    ferpaDirectoryInformationBlock: Bool,
    status: String,
};

entity Grade {
    student: Student,
    course: Course,
    gradedBy: User,
    status: String,
};

entity Course {
    instructor: Instructor,
    roster: Set<Student>,
};

action viewStudentRecord appliesTo {
    principal: [Instructor, Student, Parent, Registrar],
    resource: [StudentRecord],
    context: {
        currentDate: datetime,
        fromCampusNetwork: Bool,
    },
};

entity Role enum ["deployer", "maintainer", "clusterOperator"];

entity TeamGroup;

entity Requester {
    roles: Set<Role>,
    clearanceLevel: Long,
    grantedScope: String,
    teamGroups: Set<TeamGroup>,
};

entity ServiceAccount;

entity Namespace {
    members: Set<Requester>,
    teamGroup: TeamGroup,
    environment: String,
};

entity Workload {
    namespace: Namespace,
    creator: Requester,
    requiredVerb: String,
    replicaCount: Long,
    labels: Set<String>,
    environment: String,
};

entity NamespaceSecret {
    namespace: Namespace,
    owner: Requester,
    sensitivity: String,
    status: String,
};

entity ServiceAccountToken {
    subject: ServiceAccount,
    boundNamespace: Namespace,
    issuer: Requester,
    expirationTime: datetime,
    status: String,
};

action revokeServiceAccountToken appliesTo {
    principal: [Requester, ServiceAccount],
    resource: [ServiceAccountToken],
};

action issueServiceAccountToken appliesTo {
    principal: [Requester],
    resource: [ServiceAccountToken],
};

entity User {
    roles: Set<String>,
    controlTier: Long,
    memberships: Set<String>,
};

entity Zone {
    controller: User,
    criticality: String,
    status: String,
};

entity Actuator {
    owner: User,
    zoneGroup: Zone,
    deviceTags: Set<String>,
    maintenanceFlag: Bool,
    status: String,
};

entity CommissionRequest {
    device: Actuator,
    requester: User,
    status: String,
};

action approveCommissionRequest appliesTo {
    principal: [User],
    resource: [CommissionRequest],
    context: {
        currentTime: datetime,
        occupancyDetected: Bool,
        fromOnSiteBuildingNetwork: Bool,
        maintenanceOverride: Bool,
        withinPermittedWindow: Bool,
    },
};

entity Role enum ["Clerk", "Approver", "FinanceManager", "Auditor"];

entity InvoiceStatus enum ["Submitted", "Unsubmitted"];

entity User {
    roles: Set<Role>,
};

entity Invoice {
    creator: User,
    approver?: User,
    amount: decimal,
    surcharge: decimal,
    lineItemCount: Long,
    lineItemCountCrossesThreshold: Bool,
    status: InvoiceStatus,
    costCenter: String,
    submissionTime?: datetime,
};

entity Payment {
    invoice: Invoice,
    issuer: User,
    amount: decimal,
};

action approveInvoice appliesTo {
    principal: [User],
    resource: [Invoice],
    context: {
        currentTime: datetime,
        fromCorporateNetwork: Bool,
        emergencyDeclared: Bool,
        isBusinessHours: Bool,
    },
};

entity Role enum ["Planner", "Driver", "DispatchManager", "DepotSupervisor", "Auditor"];

entity Depot;

entity User {
    roles: Set<Role>,
};

entity Shipment {
    planner: User,
    driverOfRecord: User,
    pieceCount: Long,
    grossWeightKg: decimal,
    status: String,
    trackingCode: String,
    originDepot: Depot,
    hazmatClass: String,
    deliveryWindowEnd: datetime,
};

entity DeliveryReceipt {
    shipment: Shipment,
    recipient: String,
    signedAt: datetime,
};

action dispatchShipment appliesTo {
    principal: [User],
    resource: [Shipment],
    context: {
        currentTime: datetime,
        fromDepotNetwork: Bool,
        requestDepot?: Depot,
        isExpedited: Bool,
        proofOfDeliveryPresent: Bool,
        trackingCodeCarriesAssignedCarrierPrefix: Bool,
    },
};

action confirmDelivery appliesTo {
    principal: [User],
    resource: [DeliveryReceipt],
    context: {
        currentTime: datetime,
        fromDepotNetwork: Bool,
        requestDepot?: Depot,
        isExpedited: Bool,
        proofOfDeliveryPresent: Bool,
    },
};

entity User {
    roles: Set<Role>,
    controlTier: Long,
    groups: Set<Group>,
};

entity Role enum ["facilityManager", "zoneController", "maintenanceTechnician", "tenant"];

entity Group;

entity Actuator {
    owner: User,
    zoneGroup: Group,
    deviceTags: Set<String>,
    maintenanceFlag: Bool,
    status: String,
};

entity Zone {
    assignedController: User,
    criticalityLevel: Long,
    status: String,
};

entity CommissionRequest {
    device: Actuator,
    requestedBy: User,
    status: String,
};

action overrideZoneSchedule appliesTo {
    principal: [User],
    resource: [Zone],
};

entity LeasingAgent {
    user: User,
};

entity TransactionCoordinator {
    user: User,
};

entity Broker {
    user: User,
};

entity ComplianceOfficer {
    user: User,
};

entity Auditor {
    user: User,
};

entity User in [LeasingAgent, TransactionCoordinator, Broker, ComplianceOfficer, Auditor] {
    holdsBrokerRole: Bool,
    holdsLeasingAgentRole: Bool,
    holdsAuditorRole: Bool,
};

entity Lease {
    listingAgent: User,
    reviewedBy?: User,
    leaseCode: String,
    monthlyRent: Long,
    termInMonths: Long,
    squareFootage: Long,
    region: String,
    premisesClass: String,
    contingencies: Set<String>,
    marketSegment: String,
    fairHousingHold: Bool,
    status: String,
    signingWindowClosesAt: datetime,
    draftedBy: User,
    isHighValue: Bool,
    hasDeclaredCourtOrder: Bool,
    hasLargePremisesFootprint: Bool,
};

entity ExecutedLease;

entity AuditLog;

action draftLease appliesTo {
    principal: [User],
    resource: [Lease],
    context: {
        currentTime: datetime,
        fromBrokerageNetwork: Bool,
        counterpartyIdentityVerified: Bool,
        courtOrderDeclared: Bool,
    },
};

action reviewLease appliesTo {
    principal: [User],
    resource: [Lease],
    context: {
        currentTime: datetime,
        fromBrokerageNetwork: Bool,
        counterpartyIdentityVerified: Bool,
        courtOrderDeclared: Bool,
        highValueThreshold: Long,
        largePremisesThreshold: Long,
    },
};

action viewAuditLog appliesTo {
    principal: [User],
    resource: [AuditLog],
    context: {
        currentTime: datetime,
        fromBrokerageNetwork: Bool,
        counterpartyIdentityVerified: Bool,
        courtOrderDeclared: Bool,
    },
};

entity Role enum ["Contributor", "Reviewer", "SpaceAdmin", "Reader"];

entity User {
    roles: Set<Role>,
    clearance: Long,
    spaceMemberships: Set<Space>,
};

entity Space;

entity Page {
    author: User,
    reviewer: User,
    space: Space,
    classification: Long,
    externalSharingEnabled: Bool,
    labels: Set<String>,
    status: String,
};

action viewPage appliesTo {
    principal: [User],
    resource: [Page],
    context: {
        isOnCorporateNetwork: Bool,
        currentTime: datetime,
        emergencyAccess: Bool,
    },
};
